import React, { useState, useEffect, useMemo } from 'react';
import { createRoot } from 'react-dom/client';

// Premium dark theme with distinctive gold/bronze accents
const THEME = {
  background: '#0a0a0f',
  cardBg: '#12121a',
  cardBorder: '#1a1a2a',
  primary: '#d4af37',
  primaryLight: '#f4e4bc',
  primaryDark: '#b8860b',
  success: '#4ade80',
  successGlow: 'rgba(74, 222, 128, 0.2)',
  danger: '#f87171',
  dangerGlow: 'rgba(248, 113, 113, 0.2)',
  text: '#e8e8e8',
  textMuted: '#888899',
  accent: '#7c3aed',
  accentGlow: 'rgba(124, 58, 237, 0.3)'
};

// Custom hook for animated counters
const useAnimatedValue = (target, duration = 2000) => {
  const [value, setValue] = useState(0);
  const [isAnimating, setIsAnimating] = useState(false);

  useEffect(() => {
    if (value === target) {
      setIsAnimating(false);
      return;
    }

    setIsAnimating(true);
    const start = value;
    const end = target;
    const startTime = Date.now();

    const animate = () => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min(elapsed / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);

      setValue(Math.floor(start + (end - start) * eased));

      if (progress < 1) {
        requestAnimationFrame(animate);
      }
    };

    requestAnimationFrame(animate);
  }, [target, duration]);

  return { value, isAnimating };
};

// Donut chart for asset allocation
const AssetAllocationChart = ({ assets }) => {
  const totalValue = assets.reduce((sum, a) => sum + a.value, 0);
  let cumulativePercent = 0;

  const sectors = assets.map(asset => {
    const percent = (asset.value / totalValue) * 100;
    const startAngle = cumulativePercent * 3.6;
    cumulativePercent += percent;
    const endAngle = cumulativePercent * 3.6;

    const x1 = 80 + 60 * Math.cos((startAngle * Math.PI) / 180);
    const y1 = 80 + 60 * Math.sin((startAngle * Math.PI) / 180);
    const x2 = 80 + 60 * Math.cos((endAngle * Math.PI) / 180);
    const y2 = 80 + 60 * Math.sin((endAngle * Math.PI) / 180);

    const largeArc = endAngle - startAngle > 180 ? 1 : 0;
    const pathData = `M 80 80 L ${x1} ${y1} A 60 60 0 ${largeArc} 1 ${x2} ${y2} Z`;

    return {
      symbol: asset.symbol,
      name: asset.name,
      percent: percent,
      value: asset.value,
      color: getAssetColor(asset.symbol),
      path: pathData
    };
  });

  const colors = {
    BTC: '#F7931A',
    ETH: '#627EEA',
    SOL: '#00FFA3',
    ADA: '#0033AD'
  };

  const getAssetColor = (symbol) => colors[symbol] || '#888888';

  return (
    <div className="chart-container">
      <svg viewBox="0 0 200 200" className="donut-chart">
        <circle cx="100" cy="100" r="70" fill="none" stroke={THEME.cardBorder} strokeWidth="2" />
        {sectors.map((sector, index) => (
          <path
            key={index}
            d={sector.path}
            fill={sector.color}
            className="chart-sector"
            style={{
              transformOrigin: '100px 100px',
              transform: `rotate(${startAngle}deg)`,
              transition: 'all 0.5s ease-out',
              transformBox: 'fill-box'
            }}
          />
        ))}
        <circle cx="100" cy="100" r="35" fill={THEME.background} className="donut-center" />
      </svg>
      <div className="chart-legend">
        {sectors.map((sector, index) => (
          <div key={index} className="legend-item">
            <span 
              className="legend-color" 
              style={{ backgroundColor: sector.color }}
            />
            <span className="legend-symbol">{sector.symbol}</span>
            <span className="legend-percent">{sector.percent.toFixed(1)}%</span>
          </div>
        ))}
      </div>
    </div>
  );
};

// Price trend chart
const PriceTrendChart = ({ symbol, priceHistory, currentPrice, change24h }) => {
  const colors = {
    BTC: '#F7931A',
    ETH: '#627EEA',
    SOL: '#00FFA3',
    ADA: '#0033AD'
  };

  const chartColor = colors[symbol] || '#888888';
  const isPositive = change24h >= 0;
  const colorClass = isPositive ? THEME.success : THEME.danger;

  const maxValue = Math.max(...priceHistory);
  const minValue = Math.min(...priceHistory);
  const range = maxValue - minValue || 1;
  const height = 150;
  const width = 300;
  const padding = 20;

  const points = priceHistory.map((price, index) => {
    const x = padding + (index / (priceHistory.length - 1)) * (width - 2 * padding);
    const y = height - padding - ((price - minValue) / range) * (height - 2 * padding);
    return `${x},${y}`;
  }).join(' ');

  const areaPath = `M ${padding},${height - padding} L ${points} L ${width - padding},${height - padding} Z`;
  const linePath = `M ${points}`;

  return (
    <div className="price-chart-container">
      <div className="chart-header">
        <span className="chart-symbol">{symbol}</span>
        <span className={`chart-change ${colorClass}`}>
          {change24h >= 0 ? '+' : ''}{change24h}%
        </span>
      </div>
      <div className="chart-line">
        <svg viewBox={`0 0 ${width} ${height}`} className="trend-svg">
