      font-size: 16px;
    }

    .positive { color: var(--success); }
    .negative { color: var(--danger); }

    .stat-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
      margin-top: 24px;
    }

    .stat-item {
      text-align: center;
      padding: 16px;
      background: var(--bg-card-hover);
      border-radius: 12px;
      border: 1px solid var(--border-color);
    }

    .stat-label {
      font-size: 12px;
      color: var(--text-muted);
      margin-bottom: 8px;
    }

    .stat-value {
      font-size: 24px;
      font-weight: 600;
      color: var(--primary);
